from __future__ import annotations

import json
from copy import deepcopy

import pytest

from golden_eval.adapters.errors import CorpusValidationError
from golden_eval.adapters.jsonl_corpus import JsonlCorpusStore


def shared_payload() -> dict:
    return {
        "dataset": {
            "name": "Fixture corpus",
            "schema_version": "golden-dialogue-v0.4",
            "domain": "contract testing",
            "source_config": {"fixture": "generated by test"},
            "files": {
                "shared": "golden-dialogue-shared.json",
                "cases": "golden-dialogue-cases.jsonl",
            },
        },
        "context": {
            "note": "No SOP is defined for this fixture.",
            "profile_schema": [
                {
                    "key": "city",
                    "type": "string",
                    "description": "Customer city when explicitly provided.",
                    "value_format": "city name",
                    "examples": ["Chengdu"],
                    "updatable": True,
                    "ttl_days": None,
                }
            ],
            "profile_schema_note": "Only explicit values are recorded.",
            "available_tools": [
                {
                    "name": "lookup_store",
                    "description": "Look up a store after a city is known.",
                    "params": [],
                }
            ],
            "available_tools_note": "Only call presence is evaluated.",
            "knowledge_base_version": "fixture-v1",
        },
        "customer_memory_spec": {
            "comment": "Fixture memory contract.",
            "version": "fixture-memory-v1",
            "definition": "Retain explicit customer facts.",
        },
    }


def session_payload(session_id: str = "GD-FIXTURE-0001") -> dict:
    return {
        "session_id": session_id,
        "meta": {
            "channel": "fixture",
            "source": "fixture",
            "annotator": "test",
            "annotated_at": "2026-09-15",
            "review_status": "reviewed",
            "design_intent": "Validate v0.4 loading.",
        },
        "input": {
            "memory_before": {
                "as_of": "2026-09-15",
                "is_first_contact": True,
                "profile_snapshot": {"city": ""},
                "state_snapshot": {},
                "customer_memory": "",
                "note": "No prior memory.",
            }
        },
        "turns": [
            {
                "turn_id": f"{session_id}#T1",
                "session_id": session_id,
                "seq": 1,
                "input": {
                    "customer_messages": [
                        {"seq": 1, "type": "text", "content": "I am in Chengdu."}
                    ]
                },
                "expected": {
                    "messages": [{"seq": 1, "type": "text", "content": "Understood."}],
                    "profile_update": {"city": {"value": "Chengdu"}},
                    "profile_snapshot": {"city": "Chengdu"},
                    "tool_calls": [{"name": "lookup_store"}],
                },
                "rubric": "Acknowledge the city.",
            }
        ],
        "expected": {
            "memory_after": {
                "as_of": "2026-09-15",
                "profile_snapshot": {"city": "Chengdu"},
                "state_snapshot": {},
                "customer_memory": "Customer is in Chengdu.",
            }
        },
    }


def write_dataset(tmp_path, sessions: list[dict], shared: dict | None = None):
    (tmp_path / "golden-dialogue-shared.json").write_text(
        json.dumps(shared or shared_payload()), encoding="utf-8"
    )
    (tmp_path / "golden-dialogue-cases.jsonl").write_text(
        "".join(json.dumps(session) + "\n" for session in sessions), encoding="utf-8"
    )




def test_rejects_profile_snapshot_recursion_error_with_line_number(tmp_path) -> None:
    invalid = session_payload()
    invalid["turns"][0]["expected"]["profile_snapshot"]["city"] = "Shanghai"
    write_dataset(tmp_path, [invalid])

    with pytest.raises(CorpusValidationError, match=r"golden-dialogue-cases\.jsonl:1"):
        JsonlCorpusStore.from_directory("fixture-v1", tmp_path)


@pytest.mark.parametrize(
    "mutate, expected_error",
    [
        (
            lambda value: value["turns"][0].update({"turn_id": "wrong#T1"}),
            "turn_id must be GD-FIXTURE-0001#T1",
        ),
        (
            lambda value: value["turns"][0].update({"unexpected": True}),
            "Extra inputs are not permitted",
        ),
        (
            lambda value: value["turns"][0]["expected"]["profile_snapshot"].update(
                {"unknown": "value"}
            ),
            "profile keys mismatch",
        ),
    ],
)
def test_rejects_invalid_case_contract(tmp_path, mutate, expected_error) -> None:
    invalid = deepcopy(session_payload())
    mutate(invalid)
    if "unknown" in invalid["turns"][0]["expected"]["profile_snapshot"]:
        invalid["turns"][0]["expected"]["profile_update"]["unknown"] = {"value": "value"}
        invalid["expected"]["memory_after"]["profile_snapshot"]["unknown"] = "value"
    write_dataset(tmp_path, [invalid])

    with pytest.raises(CorpusValidationError, match=expected_error):
        JsonlCorpusStore.from_directory("fixture-v1", tmp_path)


def test_rejects_tool_not_declared_by_shared_context(tmp_path) -> None:
    invalid = session_payload()
    invalid["turns"][0]["expected"]["tool_calls"] = [{"name": "invented_tool"}]
    write_dataset(tmp_path, [invalid])

    with pytest.raises(CorpusValidationError, match="unknown tools"):
        JsonlCorpusStore.from_directory("fixture-v1", tmp_path)
